def block(t,n):
 ls=t.splitlines(True)
 for i,l in enumerate(ls):
  if l.startswith('**'+n+'**') or re.match(r'^## '+re.escape(n)+r'(?: \(|\n|$)',l):
   j=i+1
   while j<len(ls) and not re.match(r'^(?:## |\*\*)',ls[j]): j+=1
   return ''.join(ls[i:j])
 raise ValueError(n)
